      "cpp": "#include <cstdio>\n#include <vector>\n#include <algorithm>\ntypedef long long ll;\n\nint main(){\n\n    ll t; scanf(\"%lld\", &t);\n    while(t--){\n        ll n, k; scanf(\"%lld %lld\", &n, &k);\n        std::vector<ll> q(n); for(ll &x : q){scanf(\"%lld\", &x);}\n        std::vector<ll> r(n); for(ll &x : r){scanf(\"%lld\", &x);}\n        sort(q.rbegin(), q.rend());\n        sort(r.begin(), r.end());\n        ll idx(0), cnt(0);\n        for(ll p = 0; p < n; p++){if(q[p] * (r[idx] + 1) + r[idx] <= k){++idx; ++cnt;}}\n        printf(\"%lld\\n\", cnt);\n    }\n    \n}",
      "python": "import sys\n\ndef check(mid, a, k):\n    count = 1\n    curr = 0\n    for x in a:\n        if x > mid: return False\n        if curr + x > mid:\n            count += 1\n            curr = x\n        else:\n            curr += x\n    return count <= k\n\ndef solve():\n    data = sys.stdin.read().split()\n    if not data: return\n    n, k = int(data[0]), int(data[1])\n    a = [int(x) for x in data[2:2+n]]\n    \n    low = max(a)\n    high = sum(a)\n    ans = high\n    \n    while low <= high:\n        mid = (low + high) // 2\n        if check(mid, a, k):\n            ans = mid\n            high = mid - 1\n        else:\n            low = mid + 1\n            \n    print(ans)\n\nif __name__ == '__main__':\n    solve()",
