      "cpp": "#include <cstdio>\n\nint main(){\n\n    long t; scanf(\"%ld\", &t);\n    while(t--){\n        long x, y; scanf(\"%ld %ld\", &x, &y);\n        long s(x - y); s = (s > 0 ? s : -s);\n        if(s == 0){puts(\"1\");}\n        else{\n            long cnt(0);\n            for(long p = 1; p * p <= s; p++){\n                if(s % p){continue;}\n                cnt += 2 - (p * p == s);\n            }\n            printf(\"%ld\\n\", cnt);\n        }\n\n        while(x--){printf(\"1 \");}\n        while(y--){printf(\"-1 \");}\n        puts(\"\");\n    }\n\n}",
