      "cpp": "#include <cstdio>\n#include <vector>\n\nint main(){\n\n    long t; scanf(\"%ld\", &t);\n    while(t--){\n        long n; scanf(\"%ld\", &n);\n        std::vector<long> a(n); for(long &x : a){scanf(\"%ld\", &x);}\n        std::vector<long> b(n); for(long &x : b){scanf(\"%ld\", &x);}\n        std::vector<long> c(n); for(long &x : c){scanf(\"%ld\", &x);}\n\n        long long cnt(0);\n        for(long bs = 0; bs < n; bs++){\n            bool valid(true);\n            for(long p = 0; valid && p < n; p++){\n                if(a[p] >= b[(bs + p) % n]){valid = false;}\n            }\n            cnt += n * valid;\n        }\n\n        long prev(cnt); cnt = 0;\n        for(long cs = 0; cs < n; cs++){\n            bool valid(true);\n            for(long p = 0; valid && p < n; p++){\n                if(b[p] >= c[(cs + p) % n]){valid = false;}\n            }\n            cnt += prev * valid;\n        }\n\n        printf(\"%lld\\n\", cnt);\n    }\n\n}",
      "python": "import sys\n\ndef solve():\n    data = sys.stdin.read().split()\n    if not data: return\n    n, w = int(data[0]), int(data[1])\n    idx = 2\n    items = []\n    for _ in range(n):\n        items.append((int(data[idx]), int(data[idx+1])))\n        idx += 2\n        \n    dp = [0] * (w + 1)\n    for wt, val in items:\n        for cap in range(w, wt - 1, -1):\n            if dp[cap - wt] + val > dp[cap]:\n                dp[cap] = dp[cap - wt] + val\n                \n    print(dp[w])\n\nif __name__ == '__main__':\n    solve()",
