      "java": "import java.io.*;\nimport java.util.*;\n\npublic class Solution {\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        String line = br.readLine();\n        if (line == null) return;\n        StringTokenizer st = new StringTokenizer(line);\n        int n = Integer.parseInt(st.nextToken());\n        int m = Integer.parseInt(st.nextToken());\n        \n        List<List<Integer>> adj = new ArrayList<>(n + 1);\n        for (int i = 0; i <= n; i++) adj.add(new ArrayList<>());\n        \n        for (int i = 0; i < m; i++) {\n            st = new StringTokenizer(br.readLine());\n            int u = Integer.parseInt(st.nextToken());\n            int v = Integer.parseInt(st.nextToken());\n            adj.get(u).add(v);\n            adj.get(v).add(u);\n        }\n        \n        int[] dist = new int[n + 1];\n        Arrays.fill(dist, -1);\n        Queue<Integer> q = new ArrayDeque<>();\n        \n        q.add(1);\n        dist[1] = 0;\n        \n        while (!q.isEmpty()) {\n            int u = q.poll();\n            for (int v : adj.get(u)) {\n                if (dist[v] == -1) {\n                    dist[v] = dist[u] + 1;\n                    q.add(v);\n                }\n            }\n        }\n        System.out.println(dist[n]);\n    }\n}",
      "cpp": "#include <iostream>\n#include <vector>\n#include <queue>\n\nusing namespace std;\n\nint main() {\n    ios_base::sync_with_stdio(false);\n    cin.tie(NULL);\n    \n    int n, m;\n    if (!(cin >> n >> m)) return 0;\n    \n    vector<vector<int>> adj(n + 1);\n    for (int i = 0; i < m; i++) {\n        int u, v; cin >> u >> v;\n        adj[u].push_back(v);\n        adj[v].push_back(u);\n    }\n    \n    vector<int> dist(n + 1, -1);\n    queue<int> q;\n    \n    q.push(1);\n    dist[1] = 0;\n    \n    while (!q.empty()) {\n        int u = q.front(); q.pop();\n        for (int v : adj[u]) {\n            if (dist[v] == -1) {\n                dist[v] = dist[u] + 1;\n                q.push(v);\n            }\n        }\n    }\n    cout << dist[n] << \"\\n\";\n    return 0;\n}",
      "python": "import sys\nfrom collections import deque\n\ndef solve():\n    data = sys.stdin.read().split()\n    if not data: return\n    n, m = int(data[0]), int(data[1])\n    adj = [[] for _ in range(n + 1)]\n    idx = 2\n    for _ in range(m):\n        u, v = int(data[idx]), int(data[idx+1])\n        adj[u].append(v)\n        adj[v].append(u)\n        idx += 2\n        \n    dist = [-1] * (n + 1)\n    q = deque([1])\n    dist[1] = 0\n    \n    while q:\n        u = q.popleft()\n        for v in adj[u]:\n            if dist[v] == -1:\n                dist[v] = dist[u] + 1\n                q.append(v)\n                \n    print(dist[n])\n\nif __name__ == '__main__':\n    solve()",
      "idea": "Model the problem as an unweighted or weighted graph with V vertices and E edges. Use BFS queue traversal for unweighted shortest path / level-order distances, or Dijkstra with a min-priority queue for non-negative weighted edges. Track visited states with a boolean array or distance map to guarantee each vertex is relaxed at most once.",
      "complexity": "Time Complexity: O(V + E) for BFS/DFS; O((V + E) log V) for Dijkstra. Space Complexity: O(V + E) for adjacency list.",
