      "cpp": "#include <cstdio>\n#include <vector>\n\nint main(){\n\n    long t; scanf(\"%ld\", &t);\n    while(t--){\n        long n; scanf(\"%ld\", &n);\n        std::vector<long> a(n);\n        for(long p = 0; p < n; p++){scanf(\"%ld\", &a[p]);}\n\n        std::vector<int> b(n, 0);\n\n        long x(1e7); for(long p = 0; p < n; p++){if(a[p] < x){b[p] = 1; x = a[p];}}\n        x = 0; for(long p = n - 1; p >= 0; p--){if(a[p] > x){b[p] = 1; x = a[p];}}\n        for(long p = 0; p < n; p++){printf(\"%d\", b[p]);}\n        puts(\"\");\n    }\n\n}",
