      "cpp": "#include <cstdio>\n#include <vector>\n#include <algorithm>\ntypedef long long ll;\n\nint main(){\n\n    long t; scanf(\"%ld\", &t);\n    while(t--){\n        long n, l, r; scanf(\"%ld %ld %ld\", &n, &l, &r);\n        std::vector<long> vl, vs, vr;\n        ll sum(0);\n        for(long p = 1; p <= n; p++){\n            long x; scanf(\"%ld\", &x);\n            if(p < l){vl.push_back(x);}\n            else if(p <= r){vs.push_back(x); sum += x;}\n            else{vr.push_back(x);}\n        }\n\n        sort(vl.begin(), vl.end());\n        sort(vr.begin(), vr.end());\n        sort(vs.rbegin(), vs.rend());\n\n\n        ll diffA(0);\n        for(long p = 0; p < vl.size() && p < vs.size(); p++){\n            if(vl[p] < vs[p]){diffA += vl[p] - vs[p];}\n            else{break;}\n        }\n\n        ll diffB(0);\n        for(long p = 0; p < vr.size() && p < vs.size(); p++){\n            if(vr[p] < vs[p]){diffB += vr[p] - vs[p];}\n            else{break;}\n        }\n\n        printf(\"%lld\\n\", sum + (diffA < diffB ? diffA : diffB));\n    }\n\n}",
      "python": "import sys\n\ndef solve():\n    data = sys.stdin.read().split()\n    if not data: return\n    n = int(data[0])\n    a = [int(x) for x in data[1:n+1]]\n    \n    next_greater = [-1] * n\n    stack = []\n    \n    for i in range(n):\n        while stack and a[stack[-1]] < a[i]:\n            idx = stack.pop()\n            next_greater[idx] = i\n        stack.append(i)\n        \n    res = [str(a[next_greater[i]] if next_greater[i] != -1 else -1) for i in range(n)]\n    print(\" \".join(res))\n\nif __name__ == '__main__':\n    solve()",
