      "cpp": "#include <cstdio>\ntypedef long long ll;\n\nint main(){\n\n    const ll B = 63;\n\n    ll t; scanf(\"%lld\", &t);\n    while(t--){\n        ll n, k; scanf(\"%lld %lld\", &n, &k);\n        ll zv[B] = {0};\n\n        ll beauty(0);\n        for(ll p = 0; p < n; p++){\n            ll x; scanf(\"%lld\", &x);\n            for(ll p = 0; p < B; p++){\n                if(x % 2){++beauty;}\n                else{++zv[p];}\n                x /= 2;\n            }\n        }\n\n        for(ll p = 0; p < B; p++){\n            ll add = (1LL << p);  //CAUTION: need 1LL otherwise it's going to overflow\n            ll need = k / add;\n            need = (need < zv[p] ? need : zv[p]);\n            beauty += need;\n            k -= need * add;\n            //printf(\"p:%lld zvp:%lld add:%lld need:%lld beauty:%lld k:%lld\\n\", p, zv[p], add, need, beauty, k);\n        }\n\n        printf(\"%lld\\n\", beauty);\n    }\n\n}",
      "python": "import sys\n\ndef solve():\n    data = sys.stdin.read().split()\n    if not data: return\n    n = int(data[0])\n    a = [int(x) for x in data[1:n+1]]\n    \n    next_greater = [-1] * n\n    stack = []\n    \n    for i in range(n):\n        while stack and a[stack[-1]] < a[i]:\n            idx = stack.pop()\n            next_greater[idx] = i\n        stack.append(i)\n        \n    res = [str(a[next_greater[i]] if next_greater[i] != -1 else -1) for i in range(n)]\n    print(\" \".join(res))\n\nif __name__ == '__main__':\n    solve()",
