      "cpp": "#include <cstdio>\ntypedef long long ll;\n\nint main(){\n    \n    ll t; scanf(\"%lld\", &t);\n    while(t--){\n        ll n, x; scanf(\"%lld %lld\", &n, &x);\n        ll mxlen(0);\n        for(ll p = 0; p < n; p++){\n            ll a, b, c; scanf(\"%lld %lld %lld\", &a, &b, &c);\n            x -= (a * (b - 1));\n            ll len = (a * b - c);\n            mxlen = (mxlen > len ? mxlen : len);\n        }\n        \n        ll mncnt(-1);\n        if(x <= 0){mncnt = 0;}\n        else if(mxlen > 0){mncnt = (x + mxlen - 1) / mxlen;}\n        printf(\"%lld\\n\", mncnt);\n    }\n    \n}",
